package com.ems.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="leave_requests") public class LeaveRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="employee_id") private Employee employee; @Column(nullable=false) private String leaveType; private LocalDate startDate; private LocalDate endDate; private int workingDays=0; @Column(length=2000) private String reason; @Enumerated(EnumType.STRING) private LeaveStatus status=LeaveStatus.PENDING; private LocalDateTime createdAt=LocalDateTime.now(); private String rejectionReason; private boolean balanceApplied=false; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee e){employee=e;} public String getLeaveType(){return leaveType;} public void setLeaveType(String v){leaveType=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public int getWorkingDays(){return workingDays;} public void setWorkingDays(int v){workingDays=Math.max(0,v);} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public LeaveStatus getStatus(){return status;} public void setStatus(LeaveStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public String getRejectionReason(){return rejectionReason;} public void setRejectionReason(String v){rejectionReason=v;} public boolean isBalanceApplied(){return balanceApplied;} public void setBalanceApplied(boolean v){balanceApplied=v;} }
